<?php
 if ( ! defined( 'ABSPATH' ) ) { exit; } add_action( 'after_setup_theme', function () { if ( ! defined( 'HVM_UPDATE_REPO' ) || ! HVM_UPDATE_REPO ) { return; } $autoload = HVM_DIR . '/vendor/autoload.php'; $direct = HVM_DIR . '/vendor/yahnis-elsts/plugin-update-checker/plugin-update-checker.php'; if ( file_exists( $autoload ) ) { require_once $autoload; } elseif ( file_exists( $direct ) ) { require_once $direct; } else { return; } $factory = null; if ( class_exists( '\\YahnisElsts\\PluginUpdateChecker\\v5\\PucFactory' ) ) { $factory = '\\YahnisElsts\\PluginUpdateChecker\\v5\\PucFactory'; } elseif ( class_exists( '\\Puc_v4_Factory' ) ) { $factory = '\\Puc_v4_Factory'; } if ( ! $factory ) { return; } $checker = $factory::buildUpdateChecker( HVM_UPDATE_REPO, HVM_DIR . '/style.css', get_stylesheet() ); if ( method_exists( $checker, 'setBranch' ) ) { $checker->setBranch( 'main' ); } if ( defined( 'HVM_UPDATE_TOKEN' ) && HVM_UPDATE_TOKEN && method_exists( $checker, 'setAuthentication' ) ) { $checker->setAuthentication( HVM_UPDATE_TOKEN ); } } ); 